using Ariadne.NET.Analysis;
using FluentAssertions;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;

namespace Ariadne.NET.Tests.Analysis;

public class RazorSourceTests
{
    private const string GeneratedPath = "/obj/gen/Counter_razor.g.cs";

    private const string Mapped = """
        // <auto-generated/>
        namespace App
        {
            #line hidden
            public partial class Counter
            {
                void Render()
                {
        #line (6,44)-(6,74) 24 "/app/Components/Counter.razor"
        System.Console.WriteLine(_count
        #line default
        #line hidden
                    );
                }

                int _count;
            }
        }
        """;

    [Fact]
    public void MappedSpan_ReportsTheRazorFileAndLine()
    {
        var tree = Parse(Mapped);
        var span = tree.GetRoot().DescendantNodes().OfType<IdentifierNameSyntax>().First(n => string.Equals(n.Identifier.Text, "_count", StringComparison.Ordinal)).Span;

        var location = RazorSource.Locate(tree, span, RazorSource.FilePathOf(tree, CancellationToken.None) ?? tree.FilePath, CancellationToken.None);

        location.FilePath.Should().Be("/app/Components/Counter.razor");
        location.Line.Should().Be(6);
    }

    [Fact]
    public void HiddenSpan_ReportsLine1OfTheRazorFileFromAMapping()
    {
        var tree = Parse(Mapped);
        var span = ClassIdentifier(tree);

        var location = RazorSource.Locate(tree, span, RazorSource.FilePathOf(tree, CancellationToken.None) ?? tree.FilePath, CancellationToken.None);

        location.Should().Be(new SourceLocation("/app/Components/Counter.razor", 1, 1));
    }

    [Fact]
    public void HiddenSpan_WithoutMapping_UsesThePragmaChecksumPath()
    {
        var tree = Parse("""
            #pragma checksum "/app/Components/Static.razor" "{8829d00f-11b8-4213-878b-770e8597ac16}" "ab"
            // <auto-generated/>
            namespace App
            {
                #line hidden
                public partial class Static { }
            }
            """);

        RazorSource.FilePathOf(tree, CancellationToken.None).Should().Be("/app/Components/Static.razor");
        var location = RazorSource.Locate(tree, ClassIdentifier(tree), "/app/Components/Static.razor", CancellationToken.None);

        location.Should().Be(new SourceLocation("/app/Components/Static.razor", 1, 1));
    }

    [Fact]
    public void NoMappingNoPragma_UsesTheGeneratedPath()
    {
        var tree = Parse("// <auto-generated/>\nnamespace App\n{\n    public partial class Counter { }\n}\n");

        RazorSource.FilePathOf(tree, CancellationToken.None).Should().BeNull();
        var location = RazorSource.Locate(tree, ClassIdentifier(tree), tree.FilePath, CancellationToken.None);

        location.Should().Be(new SourceLocation(GeneratedPath, 4, 26));
    }

    private static SyntaxTree Parse(string text) => CSharpSyntaxTree.ParseText(text, path: GeneratedPath);

    private static Microsoft.CodeAnalysis.Text.TextSpan ClassIdentifier(SyntaxTree tree) =>
        tree.GetRoot().DescendantNodes().OfType<ClassDeclarationSyntax>().First().Identifier.Span;
}
